  (* [comment removed for export] *)
  Lemma pd_B : forall regs m (cm : Z),
    getr regs 9 = Z_to_bv 64 cm ->
    exists regs',
      msteps SEGS (mkst regs (rl dOL_24414 0x2443c) m rom) (mkst regs' (rl dF_15b38 0x15b38) m rom)
      /\ getr regs' 10 = Z_to_bv 64 cm /\ getr regs' 1 = rl dOL_24414 0x24444
      /\ regs_agree (fun r => In r [1; 10]%list) regs regs'.
Proof.
